insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('housing-documents','housing-documents',false,10485760,array['application/pdf','image/png','image/jpeg']) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=array['application/pdf','image/png','image/jpeg'];
create policy housing_documents_insert on storage.objects for insert to authenticated with check(bucket_id='housing-documents' and (storage.foldername(name))[1]=auth.uid()::text);
create policy housing_documents_read on storage.objects for select to authenticated using(bucket_id='housing-documents' and ((storage.foldername(name))[1]=auth.uid()::text or exists(select 1 from public.documents d join public.document_permissions p on p.document_id=d.id where d.storage_path=name and p.authorized_user_id=auth.uid())));
create policy housing_documents_delete on storage.objects for delete to authenticated using(bucket_id='housing-documents' and (storage.foldername(name))[1]=auth.uid()::text);
